local function ownsVisibility(edge,sx,sy)
 local b=H.sourceBox
 if sx<b[1]or sx>b[3]or sy<b[2]or sy>b[4]then return false end
 return sx>=H.previousCoreBox[1]or H.editedEdges[edge.name]==true
end
function H.unitBehindHeart(edge,x,y)
 if not edge then return false end
 local sx,sy=x*.5,(y-512)*.5;local b=H.sourceBox
 if not ownsVisibility(edge,sx,sy)then return false end
 if H.localFloorEdges[edge.name]then return false end
 for _,ring in ipairs(H.frontPipeRings[edge.name]or{})do if inRing(ring,sx,sy,.12)then return false end end
 return true
end

function H.replacesVisibility(edge,x,y)
 if not edge then return false end
 local sx,sy=x*.5,(y-512)*.5;local b=H.sourceBox
 return ownsVisibility(edge,sx,sy)
end

function H.replaceQuiet(spec)
 if not spec or spec.id~='quiet-base'then return spec end
 local out={};for k,v in pairs(spec)do out[k]=v end;out.resource=H.quietResource;return out
end
function H.replace(spec)
 if spec.id~='heart' then return spec end
 local out={};for k,v in pairs(spec)do out[k]=v end
 for _,k in ipairs({'resource','sourceBox','pixelSize','atlasPanels','atlasColumns','atlasRows','staticPanel','animatedPanel','innerPanel','outerPanel','coarsePanel','detailMinZoom'})do out[k]=H[k]end
 return out
end
function H.overlaps(spec)
 local b,c=spec.sourceBox,H.sourceBox
 return b[1]<c[3]and b[3]>c[1]and b[2]<c[4]and b[4]>c[2]
end
